def icon(name: str, width: float = 1.8, cls: str = '') -> str:
    spec = PATHS.get(name)
    if spec is None:
        raise KeyError(f'unknown icon: {name}')
    if isinstance(spec, tuple):
        svg = _F.format(p=spec[0])
    else:
        svg = _S.format(p=spec, w=width)
    if cls:
        svg = svg.replace('<svg ', f'<svg class="{cls}" ', 1)
    return svg
